public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Check if the file exists and is not directory
    if (file == null || file.isDirectory()) {
        throw new FileNotFoundException("Invalid file or file path");
    }

    // Check if the time ranges are not null or empty
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid time ranges");
    }

    // Load the file
    BufferedReader reader = new BufferedReader(new FileReader(file));

    // Read the file line by line
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    String line = null;
    while ((line = reader.readLine()) != null) {
        // Skip blank lines
        if (line.isEmpty()) {
            continue;
        }

        // Parse the line
        ThreadSnapshot snapshot = new ThreadSnapshot();
        String[] columns = line.split(",");
        snapshot.setThreadId(Long.parseLong(columns[0]));
        snapshot.setStartTime(Long.parseLong(columns[1]));
        snapshot.setEndTime(Long.parseLong(columns[2]));
        snapshot.setUnaccountedTime(Long.parseLong(columns[3]));
        snapshot.setCommands(Arrays.asList(columns[4].split(";")));

        // Check if the snapshot falls in the specified time ranges
        boolean found = false;
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (snapshot.getStartTime() >= range.getStartTime() && snapshot.getEndTime() <= range.getEndTime()) {
                found = true;
                break;
            }
        }

        // Add the snapshot to the list if it falls in one of the time ranges
        if (found) {
            snapshots.add(snapshot);
        }
    }

    // Close the reader
    reader.close();

    // Return the list of snapshots that fell in the specified time ranges
    return snapshots;

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || !file.canRead()) {
        throw new IOException("File is null or cannot be read.");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IOException("Time ranges are null or empty.");
    }

    InputStream inputStream = new FileInputStream(file);
    try {
        return parseFromInputStreamWithTimeRange(inputStream, timeRanges);
    } finally {
        inputStream.close();
    }
}

